/**
 * Nomi's service categories: generated by scripts/build-categories.mjs from scripts/categories.source.json (merged on 2026-10-08
 * from OpenStreetMap, 2GIS/Google/Yandex/Yelp category lists and Mongolian directories); edit the source, not this file. `words` are what people type for the category, in Cyrillic or Latin; matching (utils/category-match.ts) reduces
 * both to one Latin skeleton, so "шүдний эмнэлэг", "shudnii emneleg" and "shudnii emnelegt" meet.
 */
export type CategoryGroup = { id: string; mn: string; en: string };
/**
 * `osm`: OpenStreetMap tags that mean this category ("craft=tailor"); a place tagged with one is imported into it. `mode`: how the
 * customer gets the service: "callout" when the business comes to them (plumber, towing, catering), "both" when shops and come-to-you
 * services are both common (tire repair); absent means the customer goes there.
 */
export type CategoryDef = { id: string; mn: string; en: string; group: string; words: string[]; star?: boolean; osm?: string[]; mode?: 'callout' | 'both' };

